class Solution {
public:
    int minSwapsCouples(vector<int>& row) {
        int n = row.size();
        vector<int> pos(n);
        for (int i = 0; i < n; i++) pos[row[i]] = i;
        int swaps = 0;
        for (int i = 0; i < n; i += 2) {
            int partner = row[i] ^ 1;
            if (row[i + 1] != partner) {
                int partnerPos = pos[partner];
                int other = row[i + 1];
                swap(row[i + 1], row[partnerPos]);
                pos[partner] = i + 1;
                pos[other] = partnerPos;
                swaps++;
            }
        }
        return swaps;
    }
};
